import * as U from '../ui.js';
U.mount(()=>U.heading('A gentle nudge','A little reminder helps.','Set a reminder for a task or an upcoming class.',U.button('Add reminder','reminders'))+`<div class="note" style="margin-bottom:24px">${U.icon('bell')}<span>Reminders are stored in your browser. Delivery is simulated; no real email, push notification, or background alert is sent.</span></div>`+U.section('Your reminders',`<div class="table-wrap"><table><thead><tr><th>About</th><th>Remind at</th><th>Channel</th><th>Status</th><th>Actions</th></tr></thead><tbody>${U.db.reminders.slice().sort((a,b)=>a.remind_at.localeCompare(b.remind_at)).map(r=>{let t=U.db.tasks.find(t=>t.id===r.task_id),s=U.db.class_sessions.find(s=>s.id===r.class_session_id);return `<tr><td>${U.esc(t?.title||U.course(s?.course_id)?.name||'Class reminder')}</td><td>${U.date(r.remind_at)} · ${U.time(r.remind_at)}</td><td>${U.tag(r.channel)}</td><td>${U.tag(r.status,r.status==='delivered'?'blue':'')}</td><td><div class="actions">${U.edit('reminders',r.id)}${r.status==='pending'?`<button class="btn soft" data-deliver="${r.id}">Simulate delivery</button><button class="btn" data-cancel="${r.id}">Cancel</button>`:''}</div></td></tr>`}).join('')||'<tr><td colspan="5">No reminders yet.</td></tr>'}</tbody></table></div>`));
document.addEventListener('click',e=>{let b=e.target.closest('[data-deliver],[data-cancel]');if(!b)return;let r=U.db.reminders.find(r=>r.id===(b.dataset.deliver||b.dataset.cancel));r.status=b.dataset.deliver?'delivered':'cancelled';r.delivered_at=b.dataset.deliver?new Date().toISOString():null;if(b.dataset.deliver)r.attempt_count++;U.save();U.toast(b.dataset.deliver?'Notification preview delivered.':'Reminder cancelled.')});
